package com.lin.blog;
import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api") @CrossOrigin(originPatterns={"http://localhost:*","https://*.up.railway.app"}) public class ArticleController { private final ArticleRepository repo; private final AdminAuth auth; ArticleController(ArticleRepository repo,AdminAuth auth){this.repo=repo;this.auth=auth;} @GetMapping("/articles") List<Article> all(){return repo.findByPublishedTrueOrderByCreatedAtDesc();} @GetMapping("/articles/{slug}") Article one(@PathVariable String slug){return repo.findBySlugAndPublishedTrue(slug).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));} @GetMapping("/admin/articles") List<Article> admin(@RequestHeader("Authorization") String token){auth.check(token);return repo.findAll();} @PostMapping("/admin/articles") Article create(@RequestHeader("Authorization") String token,@Valid @RequestBody Article article){auth.check(token);article.id=null;return repo.save(article);} @PutMapping("/admin/articles/{id}") Article update(@RequestHeader("Authorization") String token,@PathVariable Long id,@Valid @RequestBody Article article){auth.check(token);article.id=id;if(!repo.existsById(id))throw new ResponseStatusException(HttpStatus.NOT_FOUND);return repo.save(article);} @DeleteMapping("/admin/articles/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void delete(@RequestHeader("Authorization") String token,@PathVariable Long id){auth.check(token);repo.deleteById(id);} }
